// Guards: key live + not archived; live EN hash == reviewed EN hash; live target hash == reviewed previous-target hash; last editor not a linguist unless the item carries ov (approved override). Writes unverified + AI_TO_REVIEW (29175).
const g = $('Guard Payload').first().json;
const LINGUISTS = 'qrcodelocalization@gmail.com,sabrathan@gmail.com,farahputri@gmail.com,dmluciahorea@gmail.com,roxanamoldovan25@gmail.com,mteres@terestraducciones.com,arandatrad@gmail.com,sara.guinot.trad@gmail.com,daniel@dgmultilingualservices.com,root-translations@outlook.com,austra.muizniece@gmail.com,harald.roald@gmail.com,47natcha@gmail.com,ellen.de.venter@outlook.com,ilaria.roncaglia@gmail.com,silke.luehrmann@gmx.de,boh.vozniuk@gmail.com,vidiasc@gmail.com,ivanaturcin@ymail.com,julius.valkiunas@gmail.com,jaromirvicari@me.com,karahansisman@gmail.com,katri.varvikko@gmail.com,kenneth@phraseit.dk,translation@cornell.hu,ruckova.lucia@gmail.com,marit.teichmann@gmail.com,michal.tosza@translators.org.pl,mteixeira@sacradomus.com,bruno@bsttranslations.com,nerissaneptuno@gmail.com,straus.translations@gmail.com,quentinnguyen.localize@gmail.com,therese.svardsten@gmail.com,mjlocalize@gmail.com,silis.martins@gmail.com'.split(',');
function fnv(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Live fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const live = {};
for (const k of b.keys) { const m = {}, by = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); by[t.language_iso] = String(t.modified_by_email || '').toLowerCase(); } live[k.key_id] = { m: m, by: by, arch: k.is_archived, plural: k.is_plural }; }
const byKey = {}; const skipped = []; let already = 0; let n = 0;
for (const it of g.items) {
  const L = live[it.id];
  if (!L || L.arch || L.plural) { skipped.push({ id: it.id, iso: it.iso, why: 'missing, archived or plural' }); continue; }
  if (fnv(String(L.m.en || '')) !== it.eh) { skipped.push({ id: it.id, iso: it.iso, why: 'EN changed since review' }); continue; }
  const cur = String(L.m[it.iso] || '');
  if (cur === it.t) { already++; continue; }
  if (fnv(cur) !== it.ph) { skipped.push({ id: it.id, iso: it.iso, why: 'target changed since review' }); continue; }
  if (LINGUISTS.indexOf(L.by[it.iso]) !== -1 && !it.ov) { skipped.push({ id: it.id, iso: it.iso, why: 'last edited by linguist ' + L.by[it.iso] }); continue; }
  if (g.mode === 'test' && n >= 1) { continue; }
  (byKey[it.id] = byKey[it.id] || []).push({ language_iso: it.iso, translation: it.t, is_unverified: true, is_reviewed: false, custom_translation_status_ids: [29175] });
  n++;
}
const keys = Object.keys(byKey).map(function (id) { return { key_id: Number(id), translations: byKey[id] }; });
const sent = []; for (const k of keys) { for (const t of k.translations) { sent.push({ id: k.key_id, iso: t.language_iso, t: t.translation }); } }
return [{ json: { mode: g.mode, write: g.mode !== 'check' && keys.length > 0, to_write: n, already: already, skipped: skipped, ids: g.ids, sent: sent, body: JSON.stringify({ keys: keys }) } }];

const bw = $('Build writes').first().json; const wr = $('WRITE translations').first().json;
const b = $input.first().json.body || {};
const live = {};
for (const k of (b.keys || [])) { for (const t of (k.translations || [])) { live[k.key_id + '|' + t.language_iso] = { t: t.translation, u: t.is_unverified }; } }
const mismatch = [];
for (const s of bw.sent) { const L = live[s.id + '|' + s.iso]; if (!L || L.t !== s.t) { mismatch.push({ id: s.id, iso: s.iso, live: L ? String(L.t).slice(0, 80) : null }); } }
return [{ json: { mode: bw.mode, write_status: wr.statusCode, write_errors: (wr.body && wr.body.errors) || null, sent: bw.sent.length, readback_ok: bw.sent.length - mismatch.length, mismatch: mismatch, already: bw.already, skipped: bw.skipped } }];
